// SubscribeEvents GET /v1/events:subscribe（jobs:subscribeEvents）。
// queries传递登记的查询参数；必填、类型和范围由拥有服务入口严格校验。
func (c *JobsClient) SubscribeEvents(ctx context.Context, lastEventId string, queries ...url.Values) (platform.EventStream, error) {
	requestPath := "/v1/events:subscribe"
	query := url.Values{}
	for _, values := range queries {
		for key, entries := range values {
			query[key] = append(query[key], entries...)
		}
	}
	if encoded := query.Encode(); encoded != "" {
		requestPath += "?" + encoded
	}
	reader, err := c.sse(ctx, http.MethodGet, requestPath, lastEventId)
	if err != nil {
		return nil, err
	}
	return eventEnvelopeStream{r: reader}, nil
}

// LocalizationClient 调用localization服务（自动附服务断言）。
type LocalizationClient struct{ *producerClient }

func NewLocalizationClient(baseURL, issuer string, key platform.SigningKey) *LocalizationClient {
	return &LocalizationClient{newProducerClient("localization", baseURL, issuer, key)}
}

// ListLanguages GET /v1/languages（localization:listLanguages）。
// queries传递登记的查询参数；必填、类型和范围由拥有服务入口严格校验。
func (c *LocalizationClient) ListLanguages(ctx context.Context, queries ...url.Values) (json.RawMessage, error) {
	requestPath := "/v1/languages"
	query := url.Values{}
	for _, values := range queries {
		for key, entries := range values {
			query[key] = append(query[key], entries...)
		}
	}
	if query.Get("includeDisabled") == "" {
		query.Set("includeDisabled", "false")
	}
	if encoded := query.Encode(); encoded != "" {
		requestPath += "?" + encoded
	}
	return c.do(ctx, http.MethodGet, requestPath, nil, "")
}

// ReadTranslation POST /v1/translations:read（localization:readTranslation）。
func (c *LocalizationClient) ReadTranslation(ctx context.Context, body any) (json.RawMessage, error) {
	return c.do(ctx, http.MethodPost, "/v1/translations:read", body, "")
}

